<?php
declare(strict_types=1);

/**
 * Editorial memory. Every react that is generated leaves a record (news, canonical URL, subject, people and
 * entities, central event, openings, closing question, catchphrases, strategy and the narration itself).
 * The records answer two questions before and while a new react is written:
 *
 *  - Is this news (or the same event from another source) already a react? (duplicates, never generated by itself)
 *  - Does the new text repeat the openings, closings or scenes of the latest reacts of the same character?
 *    (the catchphrases of the character are allowed to come back; the rest is not)
 */

/** How many of the latest reacts of a character are compared. */
const RADAR_EDITORIAL_WINDOW = 50;

/** @return array<string,string> key => what the strategy means (shown to the writer) */
function radar_editorial_strategies(): array
{
    return [
        'surpresa' => 'Surpresa: abre reagindo ao inesperado do fato, sem exagerar o que a matéria diz.',
        'pergunta' => 'Pergunta: abre com uma pergunta curiosa ligada ao fato principal.',
        'contraste' => 'Contraste: coloca lado a lado duas coisas que o fato revela.',
        'suspense' => 'Suspense factual: guarda o detalhe principal para a cena seguinte, sem sugerir nada que a matéria não sustente.',
        'ironia' => 'Comentário irônico leve: brinca com a situação, nunca com a pessoa.',
        'explicacao' => 'Explicação inesperada: começa pela explicação mais simples, como quem conta para a vizinha.',
    ];
}

/** Words that say nothing about the event. @return array<int,string> */
function radar_editorial_stopwords(): array
{
    return ['a', 'o', 'as', 'os', 'um', 'uma', 'uns', 'umas', 'de', 'da', 'do', 'das', 'dos', 'em', 'na', 'no', 'nas', 'nos', 'por', 'para', 'pra', 'com', 'sem', 'sob', 'sobre', 'e', 'ou', 'mas', 'que', 'se', 'ao', 'aos', 'ate', 'apos', 'entre', 'como', 'mais', 'menos', 'muito', 'seu', 'sua', 'seus', 'suas', 'ele', 'ela', 'eles', 'elas', 'foi', 'sao', 'ser', 'tem', 'ter', 'vai', 'vao', 'ja', 'nao', 'sim', 'esta', 'estao', 'esse', 'essa', 'este', 'isso', 'isto', 'quando', 'onde', 'apos', 'depois', 'antes', 'diz', 'disse', 'segundo', 'veja', 'saiba', 'entenda', 'confira', 'apos', 'durante', 'contra', 'pelo', 'pela', 'pelos', 'pelas', 'num', 'numa', 'ainda', 'tambem', 'hoje', 'ontem'];
}

/** Significant words (accents and case removed, stopwords out) of a text. @return array<int,string> */
function radar_editorial_tokens(string $text): array
{
    $stop = array_flip(radar_editorial_stopwords());
    $tokens = [];
    foreach (explode(' ', radar_fold($text)) as $word) {
        if (strlen($word) >= 3 && !isset($stop[$word])) {
            $tokens[$word] = true;
        }
    }
    return array_keys($tokens);
}

/** Names of people, places and organizations: capitalized words and acronyms (folded, unique, at most 12). @return array<int,string> */
function radar_editorial_entities(string $text): array
{
    $found = [];
    if (preg_match_all('/(?<![\p{L}])(\p{Lu}[\p{L}]{2,}|\p{Lu}{2,})(?![\p{L}])/u', $text, $matches)) {
        $skip = array_flip(['veja', 'saiba', 'entenda', 'confira', 'apos', 'como', 'para', 'por', 'segundo', 'hoje', 'ontem', 'novo', 'nova', 'tudo', 'quem', 'quando', 'onde', 'brasil']);
        foreach ($matches[1] as $name) {
            $folded = radar_fold($name);
            if ($folded !== '' && !isset($skip[$folded])) {
                $found[$folded] = true;
            }
        }
    }
    return array_slice(array_keys($found), 0, 12);
}

function radar_editorial_jaccard(array $a, array $b): float
{
    if ($a === [] || $b === []) {
        return 0.0;
    }
    $intersection = count(array_intersect($a, $b));
    $union = count(array_unique(array_merge($a, $b)));
    return $union === 0 ? 0.0 : $intersection / $union;
}

/** The URL without tracking parameters, fragment, "www." and trailing slash, so the same page always looks the same. */
function radar_editorial_canonical_url(string $url): string
{
    $url = trim($url);
    $parts = parse_url($url);
    if (!is_array($parts) || empty($parts['host'])) {
        return mb_strtolower($url);
    }
    $host = preg_replace('/^www\./', '', strtolower((string)$parts['host'])) ?? '';
    $path = rtrim((string)($parts['path'] ?? ''), '/');
    $query = [];
    parse_str((string)($parts['query'] ?? ''), $query);
    foreach (array_keys($query) as $key) {
        if (preg_match('/^(utm_|fbclid|gclid|mc_|ref$|cmpid|origin$|share|source$)/i', (string)$key) === 1) {
            unset($query[$key]);
        }
    }
    ksort($query);
    return $host . $path . ($query !== [] ? '?' . http_build_query($query) : '');
}

/** The catchphrases of a character, folded. @return array<int,string> */
function radar_editorial_phrases(string $slug): array
{
    return array_values(array_filter(array_map(static fn(mixed $phrase): string => radar_fold((string)$phrase), radar_character_get($slug)['catchphrases']), static fn(string $p): bool => $p !== ''));
}

/**
 * A text for comparison: folded, with the catchphrases taken out (they are allowed to repeat).
 *
 * @param array<int,string> $phrases from radar_editorial_phrases()
 */
function radar_editorial_plain(string $text, array $phrases): string
{
    $plain = ' ' . radar_fold($text) . ' ';
    foreach ($phrases as $folded) {
        $plain = str_replace(' ' . $folded . ' ', ' ', $plain);
    }
    return trim(preg_replace('/\s+/', ' ', $plain) ?? '');
}

/** @return array<int,string> word bigrams (single words when the text has only one) */
function radar_editorial_shingles(string $plain): array
{
    $words = $plain === '' ? [] : explode(' ', $plain);
    if (count($words) < 2) {
        return $words;
    }
    $shingles = [];
    for ($i = 0; $i < count($words) - 1; $i++) {
        $shingles[$words[$i] . ' ' . $words[$i + 1]] = true;
    }
    return array_keys($shingles);
}

/** Sentences of a text (cut after . ! ? or …). @return array<int,string> */
function radar_editorial_sentences(string $text): array
{
    return array_values(array_filter(array_map('trim', preg_split('/(?<=[.!?…])\s+/u', trim($text)) ?: []), static fn(string $s): bool => $s !== ''));
}

/**
 * The opening of a scene: its first sentence that says something besides a catchphrase ("Minha filha..." alone is not an
 * opening), else its first sentence.
 *
 * @param array<int,string> $phrases from radar_editorial_phrases()
 */
function radar_editorial_opening(string $text, array $phrases): string
{
    $sentences = radar_editorial_sentences($text);
    foreach ($sentences as $sentence) {
        if (radar_editorial_plain($sentence, $phrases) !== '') {
            return $sentence;
        }
    }
    return $sentences[0] ?? $text;
}

/** The closing question of a text: its last sentence that asks something, else its last sentence. */
function radar_editorial_closing(string $text): string
{
    $sentences = radar_editorial_sentences($text);
    foreach (array_reverse($sentences) as $sentence) {
        if (str_ends_with($sentence, '?')) {
            return $sentence;
        }
    }
    return $sentences === [] ? '' : $sentences[count($sentences) - 1];
}

/** The catchphrases of a character that the text uses. @return array<int,string> */
function radar_editorial_catchphrases_used(string $text, string $slug): array
{
    $plain = ' ' . radar_fold($text) . ' ';
    $used = [];
    foreach (radar_character_get($slug)['catchphrases'] as $phrase) {
        $folded = radar_fold((string)$phrase);
        if ($folded !== '' && str_contains($plain, ' ' . $folded . ' ')) {
            $used[] = (string)$phrase;
        }
    }
    return $used;
}

/** Why a record matches a news item. @return array<string,string> */
function radar_editorial_match_labels(): array
{
    return [
        'same_news' => 'a mesma notícia',
        'same_url' => 'a mesma matéria (mesmo endereço)',
        'same_event' => 'o mesmo acontecimento noticiado por outra fonte',
        'similar_event' => 'um acontecimento muito parecido',
    ];
}

/**
 * Reacts already produced for the same news or the same event (other source, same cluster, same people and
 * facts). Nothing is generated from here: the caller shows the warning and the user decides.
 *
 * @param array<string,mixed> $news decoded news item
 * @return array<int,array<string,mixed>>
 */
function radar_editorial_duplicates(array $news, ?string $slug = null): array
{
    $newsId = (int)($news['id'] ?? 0);
    $row = $newsId > 0 ? radar_db_one('SELECT cluster_id, published_at FROM news WHERE id = ?', [$newsId]) : null;
    $cluster = $row !== null && $row['cluster_id'] !== null ? (int)$row['cluster_id'] : null;
    $published = $row !== null && $row['published_at'] !== null ? (int)$row['published_at'] : null;
    $url = radar_editorial_canonical_url((string)($news['url'] ?? ''));
    $tokens = radar_editorial_tokens((string)($news['title'] ?? ''));
    $entities = radar_editorial_entities((string)($news['title'] ?? ''));
    $labels = radar_editorial_match_labels();
    $matches = [];
    $rows = radar_db_all('SELECT h.*, COALESCE((SELECT n.cluster_id FROM news n WHERE n.id = h.news_id), h.cluster_id) AS current_cluster, s.news_title AS script_title, s.news_source AS script_source FROM editorial_history h JOIN scripts s ON s.id = h.script_id ORDER BY h.created_at DESC, h.id DESC LIMIT 500');
    foreach ($rows as $history) {
        $type = null;
        $score = 0.0;
        if ($newsId > 0 && (int)$history['news_id'] === $newsId) {
            [$type, $score] = ['same_news', 1.0];
        } elseif ($url !== '' && $history['canonical_url'] === $url) {
            [$type, $score] = ['same_url', 1.0];
        } elseif ($cluster !== null && $history['current_cluster'] !== null && (int)$history['current_cluster'] === $cluster) {
            [$type, $score] = ['same_event', 0.9];
        } else {
            $other = $history['title_key'] === '' ? [] : explode(' ', (string)$history['title_key']);
            $similarity = radar_editorial_jaccard($tokens, $other);
            $sharedEntities = count(array_intersect($entities, (array)json_decode((string)$history['entities'], true)));
            $close = $published === null || $history['event_date'] === null || abs($published - (int)$history['event_date']) <= 7 * 86400;
            if ($close && ($similarity >= 0.6 || ($similarity >= 0.4 && $sharedEntities >= 2))) {
                [$type, $score] = ['similar_event', $similarity];
            }
        }
        if ($type === null) {
            continue;
        }
        $matches[] = [
            'script_id' => (int)$history['script_id'], 'news_id' => $history['news_id'] !== null ? (int)$history['news_id'] : null,
            'title' => (string)$history['script_title'], 'source' => (string)$history['script_source'],
            'character' => (string)$history['character_slug'], 'character_name' => radar_character_get((string)$history['character_slug'])['name'],
            'type' => $type, 'type_label' => $labels[$type], 'similarity' => round($score, 2), 'is_update' => (int)$history['is_update'] === 1,
            'created_at' => gmdate(DATE_ATOM, (int)$history['created_at']),
        ];
    }
    usort($matches, static fn(array $a, array $b): int => $b['similarity'] <=> $a['similarity'] ?: strcmp($b['created_at'], $a['created_at']));
    return array_slice($matches, 0, 5);
}

/**
 * The text of the warning for a list of duplicates.
 *
 * @param array<int,array<string,mixed>> $matches
 */
function radar_editorial_duplicate_message(array $matches): string
{
    $first = $matches[0];
    return 'Já existe um react para ' . $first['type_label'] . ': “' . $first['title'] . '” (roteiro #' . $first['script_id'] . ', ' . $first['character_name'] . '). Nada foi gerado. Abra o roteiro existente, gere mesmo assim ou, se houve um fato novo, gere como atualização.';
}

/**
 * Remember a script: what it was about, how it opened and closed, which catchphrases it used and the whole text.
 * Called for every react that is generated or changed.
 */
function radar_editorial_record(int $scriptId): void
{
    $row = radar_db_one('SELECT * FROM scripts WHERE id = ?', [$scriptId]);
    if ($row === null) {
        return;
    }
    $slug = radar_character_slug($row['character_slug'] ?? null);
    $scenes = radar_db_all('SELECT narration, emotion FROM react_scenes WHERE script_id = ? ORDER BY scene_number', [$scriptId]);
    if ($scenes !== []) {
        $narrations = array_map(static fn(array $s): string => (string)$s['narration'], $scenes);
        $reaction = (string)$scenes[count($scenes) - 1]['emotion'];
    } else {
        $narrations = array_values(array_filter([(string)$row['hook'], (string)$row['script'], trim((string)$row['commentary'] . ' ' . (string)$row['cta'])], static fn(string $t): bool => $t !== ''));
        $reaction = (string)$row['expression'];
    }
    $news = $row['news_id'] !== null ? radar_db_one('SELECT cluster_id, published_at, summary, url FROM news WHERE id = ?', [(int)$row['news_id']]) : null;
    $phrases = radar_editorial_phrases($slug);
    $last = $narrations === [] ? '' : $narrations[count($narrations) - 1];
    $full = implode("\n\n", $narrations);
    $title = (string)$row['news_title'];
    radar_db_exec('DELETE FROM editorial_history WHERE script_id = ?', [$scriptId]);
    radar_db_exec(
        'INSERT INTO editorial_history (script_id, news_id, cluster_id, character_slug, character_version, canonical_url, title_key, subject, entities, event, event_date, strategy, reaction_type, openings, closing, catchphrases, narration, is_update, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [
            $scriptId, $row['news_id'] !== null ? (int)$row['news_id'] : null, $news !== null && $news['cluster_id'] !== null ? (int)$news['cluster_id'] : null, $slug, (int)($row['character_version'] ?? 1),
            radar_editorial_canonical_url((string)$row['news_url']), implode(' ', radar_editorial_tokens($title)), mb_substr($title, 0, 200),
            json_encode(radar_editorial_entities($title . ' ' . (string)($news['summary'] ?? '')), JSON_UNESCAPED_UNICODE), mb_substr($title, 0, 300),
            $news !== null && $news['published_at'] !== null ? (int)$news['published_at'] : null, (string)($row['strategy'] ?? ''), mb_substr($reaction, 0, 60),
            json_encode(array_map(static fn(string $n): string => radar_editorial_opening($n, $phrases), $narrations), JSON_UNESCAPED_UNICODE),
            radar_editorial_closing($last), json_encode(radar_editorial_catchphrases_used($full, $slug), JSON_UNESCAPED_UNICODE), $full,
            !empty($row['update_of']) ? 1 : 0, (int)$row['created_at'],
        ]
    );
}

/** The latest records of a character, newest first. @return array<int,array<string,mixed>> */
function radar_editorial_recent(?string $slug = null, int $limit = RADAR_EDITORIAL_WINDOW, ?int $exceptScript = null): array
{
    $slug = radar_character_slug($slug);
    $rows = radar_db_all('SELECT * FROM editorial_history WHERE character_slug = ? AND (script_id IS NULL OR script_id <> ?) ORDER BY created_at DESC, id DESC LIMIT ' . max(1, min(200, $limit)), [$slug, $exceptScript ?? 0]);
    foreach ($rows as &$row) {
        $row['openings'] = (array)json_decode((string)$row['openings'], true);
        $row['catchphrases'] = (array)json_decode((string)$row['catchphrases'], true);
        $row['paragraphs'] = array_values(array_filter(array_map('trim', preg_split('/\R\s*\R/u', (string)$row['narration']) ?: [])));
    }
    return $rows;
}

/**
 * Compare the scenes of a new text with the latest reacts of the same character: the opening of the first scene, the
 * closing question and every scene against the scene in the same place. Catchphrases do not count.
 *
 * @param array<int,string> $narrations one text per scene
 * @return array<int,array{scene:int,kind:string,with:int,score:float,text:string}> issues (empty = nothing repeated)
 */
function radar_editorial_check(array $narrations, string $slug, ?int $exceptScript = null): array
{
    $issues = [];
    $narrations = array_values($narrations);
    if ($narrations === []) {
        return [];
    }
    $phrases = radar_editorial_phrases($slug);
    $firstWords = static fn(string $plain, int $n): string => implode(' ', array_slice(explode(' ', $plain), 0, $n));
    $opening = radar_editorial_plain(radar_editorial_opening($narrations[0], $phrases), $phrases);
    $lastIndex = count($narrations) - 1;
    $closing = radar_editorial_plain(radar_editorial_closing($narrations[$lastIndex]), $phrases);
    $openingRaw = radar_fold(radar_editorial_opening($narrations[0], $phrases));
    foreach (radar_editorial_recent($slug, RADAR_EDITORIAL_WINDOW, $exceptScript) as $position => $history) {
        $sid = (int)$history['script_id'];
        $oldOpening = radar_editorial_plain((string)($history['openings'][0] ?? ''), $phrases);
        // An opening made only of a catchphrase may come back, but never in the next videos in a row.
        if ($opening === '' && $position < 3 && $openingRaw !== '' && $openingRaw === radar_fold((string)($history['openings'][0] ?? ''))) {
            $issues[] = ['scene' => 1, 'kind' => 'abertura', 'with' => $sid, 'score' => 1.0, 'text' => (string)($history['openings'][0] ?? '')];
        }
        if ($opening !== '' && $oldOpening !== '') {
            $score = radar_editorial_jaccard(radar_editorial_shingles($opening), radar_editorial_shingles($oldOpening));
            if ($opening === $oldOpening || $score >= 0.6 || (count(explode(' ', $opening)) >= 4 && $firstWords($opening, 4) === $firstWords($oldOpening, 4))) {
                $issues[] = ['scene' => 1, 'kind' => 'abertura', 'with' => $sid, 'score' => round($opening === $oldOpening ? 1.0 : max($score, 0.6), 2), 'text' => (string)($history['openings'][0] ?? '')];
            }
        }
        $oldClosing = radar_editorial_plain((string)$history['closing'], $phrases);
        if ($closing !== '' && $oldClosing !== '') {
            $score = radar_editorial_jaccard(radar_editorial_shingles($closing), radar_editorial_shingles($oldClosing));
            if ($closing === $oldClosing || $score >= 0.6) {
                $issues[] = ['scene' => $lastIndex + 1, 'kind' => 'fechamento', 'with' => $sid, 'score' => round($closing === $oldClosing ? 1.0 : $score, 2), 'text' => (string)$history['closing']];
            }
        }
        // The reaction of the last scene (what comes before the closing question) is compared apart from the question.
        if (count($narrations) > 1 && isset($history['paragraphs'][$lastIndex])) {
            $reaction = static fn(string $text): string => radar_editorial_plain(implode(' ', array_slice(radar_editorial_sentences($text), 0, max(0, count(radar_editorial_sentences($text)) - 2))), $phrases);
            $mine = $reaction($narrations[$lastIndex]);
            $theirs = $reaction((string)$history['paragraphs'][$lastIndex]);
            if ($mine !== '' && $theirs !== '' && ($mine === $theirs || radar_editorial_jaccard(radar_editorial_shingles($mine), radar_editorial_shingles($theirs)) >= 0.6)) {
                $issues[] = ['scene' => $lastIndex + 1, 'kind' => 'reação', 'with' => $sid, 'score' => 1.0, 'text' => mb_substr((string)$history['paragraphs'][$lastIndex], 0, 120)];
            }
        }
        foreach ($narrations as $index => $narration) {
            $old = $history['paragraphs'][$index] ?? null;
            if ($old === null || $index === 0 || $index === $lastIndex) {
                continue;
            }
            $score = radar_editorial_jaccard(radar_editorial_shingles(radar_editorial_plain($narration, $phrases)), radar_editorial_shingles(radar_editorial_plain($old, $phrases)));
            if ($score >= 0.55) {
                $issues[] = ['scene' => $index + 1, 'kind' => 'cena', 'with' => $sid, 'score' => round($score, 2), 'text' => mb_substr($old, 0, 120)];
            }
        }
    }
    return $issues;
}

/**
 * The creative strategy for a new react: one of the allowed ones, the least used in the latest reacts, never the one used
 * last when another is possible. With a seed the choice is repeatable (tests); without one, ties are drawn.
 *
 * @param array<int,string> $allowed strategy keys
 */
function radar_editorial_pick_strategy(string $slug, array $allowed, ?int $seed = null): string
{
    $allowed = array_values(array_intersect(array_keys(radar_editorial_strategies()), $allowed));
    if ($allowed === []) {
        $allowed = array_keys(radar_editorial_strategies());
    }
    $history = array_slice(radar_editorial_recent($slug, 12), 0, 12);
    $uses = array_fill_keys($allowed, 0);
    foreach ($history as $row) {
        if (isset($uses[$row['strategy']])) {
            $uses[$row['strategy']]++;
        }
    }
    $last = $history[0]['strategy'] ?? '';
    $pool = array_values(array_filter($allowed, static fn(string $s): bool => $s !== $last));
    $pool = $pool === [] ? $allowed : $pool;
    $min = min(array_map(static fn(string $s): int => $uses[$s], $pool));
    $least = array_values(array_filter($pool, static fn(string $s): bool => $uses[$s] === $min));
    return $least[$seed === null ? random_int(0, count($least) - 1) : (int)(crc32((string)$seed) % count($least))];
}
